    'ops_accounts_partnerships_hint' => 'অ্যাকাউন্টস স্টাফ পাবলিক ও ফিল্ড-সেলস আবেদনও পর্যালোচনা করতে পারেন',
    'ops_find_partner' => 'নাম বা ডিলার কোড দিয়ে পার্টনার খুঁজুন (সর্বোচ্চ ২০০ মিল)',
