    'ops_deployment_hint' => 'প্রিভিউ ডেটা অপরিবর্তিত থাকে। ডিপ্লয়মেন্ট চেক আর্থিক পোস্টিং চালু করে না বা উদ্বোধনী ব্যালেন্স অনুমোদন করে না।',
    'ops_go_live_warnings' => 'গো-লাইভ সতর্কতা (প্রস্তুতি ব্লক করে না; প্রোডাকশন ট্রাফিকের আগে সমাধান করুন)',
    'ops_warn_sms_driver_logging_only' => 'SMS ড্রাইভার শুধু লগ করছে — পার্টনার OTP গো-লাইভের আগে আসল SMS প্রোভাইডার কনফিগার করুন।',
    'ops_warn_mail_driver_logging_only' => 'মেইল ড্রাইভার শুধু লগ করছে — পাসওয়ার্ড রিসেট ট্রাফিকের আগে SMTP/SES/Postmark কনফিগার করুন।',
    'ops_warn_mail_from_address_is_example_placeholder' => 'MAIL_FROM_ADDRESS এখনও @example.com — গো-লাইভের আগে আসল ফ্রম অ্যাড্রেস সেট করুন।',
    'ops_warn_mail_smtp_host_is_local_development' => 'SMTP হোস্ট লোকাল Mailpit/ডেভ মেইলের মতো — MAIL_HOST প্রোডাকশন মেইলে নির্দেশ করুন।',
    'ops_warn_login_otp_requires_real_sms_before_go_live' => 'লগইন OTP চালু আছে কিন্তু SMS এখনও লগ-অনলি — আসল প্রোভাইডার দিয়ে OTP এন্ড-টু-এন্ড যাচাই করুন।',
    'ops_warn_place_code_catalog_incomplete' => 'প্লেস-কোড ক্যাটালগ অসম্পূর্ণ — পার্টনার অনবোর্ডিং গো-লাইভের আগে BangladeshPlaceCodeSeeder চালান (কমপক্ষে ৮টি বিভাগ + ৬৪টি জেলা)।',
    'ops_warn_area_dealer_assignments_missing' => 'সক্রিয় এরিয়া-ডিলার অ্যাসাইনমেন্ট নেই — প্লেস কোড সিডের পর কমপক্ষে একজন বিভাগ/জেলা/উপজেলা/ইউনিয়ন ডিলার সিট করুন, নাহলে ভৌগোলিক কমিশন পুল আনঅ্যাসাইনড রিজার্ভে পোস্ট হবে।',
    'ops_warn_opening_balances_unverified' => 'উদ্বোধনী ব্যালেন্স দ্বৈত-নিয়ন্ত্রণ যাচাই হয়নি — MADINA_FINANCIAL_ACTIVATION=true করার আগে উদ্বোধনী প্রস্তুত ও যাচাই করুন।',
    'ops_warn_payment_collection_accounts_missing' => 'সক্রিয় পেমেন্ট কালেকশন অ্যাকাউন্ট নেই — পার্টনার পেমেন্ট ক্লেইম গো-লাইভের আগে কালেকশন গ্রহণ করে এমন কমপক্ষে একটি ব্যাংক/এমএফএস অ্যাকাউন্ট কনফিগার করুন।',
    'ops_warn_payment_payout_accounts_missing' => 'সক্রিয় পেমেন্ট পে-আউট অ্যাকাউন্ট নেই — পার্টনার উইথড্রয়াল গো-লাইভের আগে পে-আউট করতে পারে এমন কমপক্ষে একটি ব্যাংক/এমএফএস অ্যাকাউন্ট কনফিগার করুন।',
    'ops_warn_queue_driver_is_sync' => 'কিউ ড্রাইভার sync/null — আমদানি ও ব্যাকগ্রাউন্ড পে-আউট গো-লাইভের আগে টেকসই কিউ ওয়ার্কার (database/redis) চালান।',
    'ops_warn_scheduler_heartbeat_missing' => 'সিডিউলার হার্টবিট নেই — পরিপক্কতা রিলিজ ও ব্যাকআপ সময়মতো রাখতে `php artisan schedule:work` (বা cron) চালান।',
    'ops_warn_queue_worker_heartbeat_missing' => 'কিউ ওয়ার্কার হার্টবিট নেই — আমদানি ও ব্যাকগ্রাউন্ড জব চালাতে `php artisan queue:work --queue=imports,default` চালান।',
    'ops_warn_debug_mode_enabled' => 'APP_DEBUG চালু আছে — প্রোডাকশন ট্রাফিকের আগে ডিবাগ বন্ধ করুন যাতে স্ট্যাক ট্রেস ও পরিবেশের বিস্তারিত গোপন থাকে।',
    'ops_warn_backups_not_configured' => 'এনক্রিপ্টেড ব্যাকআপ কনফিগার নেই — MADINA_BACKUPS_ENABLED ও ৩২+ অক্ষরের MADINA_BACKUP_PASSWORD সেট করুন, তারপর app:backup-verify দিয়ে যাচাই করুন।',
    'ops_warn_app_environment_not_production' => 'APP_ENV প্রোডাকশন নয় — পাবলিক ট্রাফিকের আগে লাইভ হোস্টে APP_ENV=production সেট করুন।',
    'ops_warn_app_url_not_https' => 'APP_URL HTTPS নয় — প্রোডাকশন ট্রাফিকের আগে https:// পাবলিক URL সেট করুন।',
    'ops_warn_session_cookies_not_hardened' => 'সেশন কুকি শক্ত করা নেই — প্রোডাকশন HTTPS ট্রাফিকের জন্য SESSION_SECURE_COOKIE=true ও SESSION_ENCRYPT=true সেট করুন।',
    'ops_warn_app_key_missing_or_weak' => 'APP_KEY নেই বা খুব ছোট — প্রোডাকশন ট্রাফিকের আগে শক্তিশালী অ্যাপ্লিকেশন কী তৈরি করুন।',
    'ops_warn_trusted_proxies_not_configured' => 'APP_URL HTTPS কিন্তু TRUSTED_PROXIES খালি — TLS টার্মিনেশনের পেছনে HTTPS ও ক্লায়েন্ট IP সনাক্তকরণের জন্য লোড-ব্যালেন্সার/প্রক্সি CIDR সেট করুন।',
